import itertools
import json

def solve():
    # Define the puzzle attributes (input variables)
    houses = [1, 2]  # left to right
    names = ['Arnold', 'Eric']
    hair_colors = ['black', 'brown']
    favorite_sports = ['basketball', 'soccer']
    favorite_smoothies = ['desert', 'cherry']

    # Helper to find index of a value in a permutation
    def pos(perm, value):
        return perm.index(value)

    solution = None

    # Iterate over all permutations for each attribute set
    for name_perm in itertools.permutations(names):
        for hair_perm in itertools.permutations(hair_colors):
            # Clue 3: Arnold is somewhere to the left of the person who has black hair.
            if not (pos(name_perm, 'Arnold') < pos(hair_perm, 'black')):
                continue

            for sport_perm in itertools.permutations(favorite_sports):
                # Clue 2: The person who has brown hair is the person who loves basketball.
                if pos(hair_perm, 'brown') != pos(sport_perm, 'basketball'):
                    continue

                for smoothie_perm in itertools.permutations(favorite_smoothies):
                    # Clue 1: The Desert smoothie lover is Arnold.
                    if pos(smoothie_perm, 'desert') != pos(name_perm, 'Arnold'):
                        continue

                    # If all constraints are satisfied, record the solution
                    rows = []
                    for i, house in enumerate(houses):
                        rows.append([
                            str(house),
                            name_perm[i],
                            hair_perm[i],
                            sport_perm[i],
                            smoothie_perm[i],
                        ])
                    solution = {
                        "solution": {
                            "header": ["House", "name", "hair colors", "favorite sports", "favorite smoothie"],
                            "rows": rows
                        }
                    }
                    # Assuming a unique solution; break once found
                    return solution

    return {"solution": {"header": ["House", "name", "hair colors", "favorite sports", "favorite smoothie"], "rows": []}}

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, indent=2))
